import * as THREE from 'three/webgpu';
import { mix, vec3 } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 0, 0);
  group.userData.handlers = {};

  const timelines = [];
  const disposables = [];

  // ============================================================================
  // BACKDROP: 7 x 5.5 plane at z=-1.5 with vertical gradient
  // ============================================================================
  const backdropGeom = new THREE.PlaneGeometry(7, 5.5);
  disposables.push(backdropGeom);

  const backdropMaterial = new THREE.MeshBasicNodeMaterial({
    colorNode: mix(
      vec3(0.04, 0.04, 0.06),
      vec3(0.075, 0.075, 0.10)
    ),
    side: THREE.DoubleSide
  });
  disposables.push(backdropMaterial);

  const backdrop = new THREE.Mesh(backdropGeom, backdropMaterial);
  backdrop.position.z = -1.5;
  group.add(backdrop);

  // ============================================================================
  // TEXT RENDERING via fontAtlas
  // ============================================================================
  const heroMeshes = [];
  const subheadMeshes = [];
  let lastGlyphDelay = 0;

  // Caption: "NOVA ATELIER / CALIBRE PROGRAM" at y=1.15
  // JetBrains Mono 18px 700 uppercase
  if (ctx.fontAtlas) {
    const captionMeshes = ctx.fontAtlas.createTextMeshes(
      "NOVA ATELIER / CALIBRE PROGRAM",
      {
        fontSize: 18,
        fontFamily: "JetBrains Mono",
        fontWeight: 700,
        letterSpacing: 0.12,
        lineHeight: 1.4,
        color: 0xe8ecf2
      }
    );

    if (Array.isArray(captionMeshes)) {
      const captionGroup = new THREE.Group();
      captionGroup.position.y = 1.15;
      captionMeshes.forEach(mesh => {
        if (mesh.material) {
          mesh.material.transparent = true;
        }
        captionGroup.add(mesh);
      });
      group.add(captionGroup);
    }
  }

  // Hero: "TIME, MACHINED." at y=0.4
  // Lora 600, em height 0.62 (fontSize 124px ~ 0.62 scene units)
  // Word z-offsets: "TIME," at z=0.12, "MACHINED." at z=-0.12
  if (ctx.fontAtlas) {
    const heroMeshGroup = ctx.fontAtlas.createTextMeshes(
      "TIME, MACHINED.",
      {
        fontSize: 124,
        fontFamily: "Lora",
        fontWeight: 600,
        letterSpacing: -0.01,
        lineHeight: 1.05,
        color: 0xe8ecf2,
        returnIndividualGlyphs: true
      }
    );

    if (Array.isArray(heroMeshGroup)) {
      const heroGroup = new THREE.Group();
      heroGroup.position.y = 0.4;

      const heroText = "TIME, MACHINED.";
      const words = ["TIME,", "MACHINED."];
      const zOffsets = [0.12, -0.12];
      let wordIdx = 0;
      let charCount = 0;

      heroMeshGroup.forEach((mesh, glyphIdx) => {
        if (charCount >= (words[wordIdx]?.length || 0)) {
          charCount = 0;
          wordIdx++;
        }

        const zOffset = zOffsets[wordIdx] || 0;
        mesh.position.z = zOffset;

        if (mesh.material) {
          mesh.material.transparent = true;
          mesh.material.opacity = 0;
        }
        mesh.userData.glyphIndex = glyphIdx;

        heroGroup.add(mesh);
        heroMeshes.push(mesh);
        charCount++;
      });

      group.add(heroGroup);
    }
  }

  // Subhead: "Every calibre begins as a solid billet." at y=-0.65
  // JetBrains Mono 40px 400
  if (ctx.fontAtlas) {
    const subheadMeshGroup = ctx.fontAtlas.createTextMeshes(
      "Every calibre begins as a solid billet.",
      {
        fontSize: 40,
        fontFamily: "JetBrains Mono",
        fontWeight: 400,
        letterSpacing: 0.02,
        lineHeight: 1.35,
        color: 0xe8ecf2,
        returnIndividualGlyphs: true
      }
    );

    if (Array.isArray(subheadMeshGroup)) {
      const subheadGroup = new THREE.Group();
      subheadGroup.position.y = -0.65;

      subheadMeshGroup.forEach(mesh => {
        if (mesh.material) {
          mesh.material.transparent = true;
          mesh.material.opacity = 0;
        }
        subheadGroup.add(mesh);
        subheadMeshes.push(mesh);
      });

      group.add(subheadGroup);
    }
  }

  // ============================================================================
  // ACCENT UNDERLINE: 2.6 x 0.045 plane
  // Emissive #ff2a38, intensity 1.2, at y=-0.05
  // ============================================================================
  const underlineGeom = new THREE.PlaneGeometry(2.6, 0.045);
  disposables.push(underlineGeom);

  const underlineMaterial = new THREE.MeshBasicNodeMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.2,
    transparent: true,
    opacity: 1
  });
  disposables.push(underlineMaterial);

  const underline = new THREE.Mesh(underlineGeom, underlineMaterial);
  underline.position.set(0, -0.05, 0.13);
  underline.scale.x = 0;
  group.add(underline);

  // ============================================================================
  // ANIMATIONS
  // ============================================================================
  const easeKinetic = "cubic-bezier(0.215, 0.61, 0.355, 1)";
  const easeSettle = "cubic-bezier(0.165, 0.84, 0.44, 1)";
  const easeFade = "cubic-bezier(0.25, 0.46, 0.45, 0.94)";

  // Hero kinetic entrance: per-glyph y +0.35 → 0, opacity 0 → 1
  // 700ms each, 60ms stagger left to right
  const heroTimeline = gsap.timeline({ paused: true });

  heroMeshes.forEach((mesh, i) => {
    const delay = i * 0.06; // 60ms stagger

    heroTimeline.fromTo(
      mesh.position,
      { y: 0.35 },
      { y: 0, duration: 0.7, ease: easeKinetic },
      delay
    );

    heroTimeline.fromTo(
      mesh.material,
      { opacity: 0 },
      { opacity: 1, duration: 0.7, ease: easeKinetic },
      delay
    );
  });

  timelines.push(heroTimeline);

  // Calculate timing for weighted settle (triggered by final glyph + 120ms)
  lastGlyphDelay = (heroMeshes.length - 1) * 0.06 + 0.7;

  // Weighted settle: scale 1.04 → 1.0, 900ms cubic-bezier(0.165,0.84,0.44,1)
  const settleTimeline = gsap.timeline({ paused: true });

  settleTimeline.fromTo(
    group.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: easeSettle },
    lastGlyphDelay
  );

  // Accent underline: scaleX 0 → 1, 500ms, starting 120ms after last glyph
  settleTimeline.fromTo(
    underline.scale,
    { x: 0 },
    { x: 1, duration: 0.5, ease: easeFade },
    lastGlyphDelay + 0.12
  );

  timelines.push(settleTimeline);

  // Subhead fade-up: opacity 0 → 1, y +0.2 → 0, 500ms
  const subheadTimeline = gsap.timeline({ paused: true });

  subheadMeshes.forEach(mesh => {
    subheadTimeline.fromTo(
      mesh.position,
      { y: 0.2 },
      { y: 0, duration: 0.5, ease: easeFade },
      lastGlyphDelay + 0.5
    );

    subheadTimeline.fromTo(
      mesh.material,
      { opacity: 0 },
      { opacity: 1, duration: 0.5, ease: easeFade },
      lastGlyphDelay + 0.5
    );
  });

  timelines.push(subheadTimeline);

  // Play all timelines
  heroTimeline.play();
  settleTimeline.play();
  subheadTimeline.play();

  // ============================================================================
  // APPLY CINEMATIC PRIMITIVES
  // ============================================================================
  if (ctx.primitives?.['kinetic-text']) {
    ctx.primitives['kinetic-text'](group, {
      staggerMs: 60,
      riseUnits: 0.35
    });
  }

  // ============================================================================
  // CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    disposables.forEach(item => item.dispose());
    [heroMeshes, subheadMeshes].flat().forEach(mesh => {
      if (mesh?.geometry) mesh.geometry.dispose();
      if (mesh?.material) mesh.material.dispose();
    });
  };

  return group;
}
